    "judul": "Bursa Tuntaskan Pembersihan 18 Emiten Bermasalah",
    "isi": "Hari ini BEI resmi mencabut status tercatat 18 emiten sekaligus, termasuk saham SKYB dan SUGI, serta saham dan lima obligasi TDPM dan TELE. Obligasi TDPM dan TELE turut dicabut meski kewajiban bayar bunga dan pokok ke pemegang obligasi tetap berlaku, sehingga yang hilang bukan cuma saham tapi juga pasar resmi bagi surat utangnya. Pembersihan ini melanjutkan arah yang sama dengan edisi kemarin soal delisting emiten bermasalah, dan hari ini menegaskan arah itu benar-benar tuntas serentak untuk puluhan nama sekaligus. Yang akan menunjukkan apakah siklus ini berhenti atau berlanjut adalah daftar suspensi BEI berikutnya yang mendekati ambang 24 bulan sesuai aturan delisting paksa."
