  "judul": "Buyback Meluas, Utang BUMN Karya Menumpuk, Dilusi Berlanjut",
  "ringkas": "Buyback besar-besaran meluas ke emiten raksasa saat IHSG justru menguat, sementara tekanan utang di BUMN karya dan pola dilusi saham di emiten kecil terus berjalan tanpa jeda.",
  "benang": [
   {
    "judul": "Tekanan Utang BUMN Karya Melebar",
    "isi": "Dalam sepekan terakhir, tekanan utang di perusahaan konstruksi pelat merah terus menumpuk. RUPSU sukuk WIKA dua kali gagal mengambil keputusan pada 21 Oktober, pertama karena suara setuju penyelesaian bagi hasil ke-14 dan ke-15 hanya 48,2 persen, lalu usulan penjadwalan ulang bagi hasil ke-22 dan ke-23 ditolak 71,4 persen suara, keduanya jauh dari syarat 75 persen. PTPP bahkan sudah gagal membayar bunga obligasi dan bagi hasil sukuk yang jatuh tempo 22 Oktober, sehingga BEI melanjutkan suspensi sahamnya dengan alasan eksplisit soal kelangsungan usaha. ADHI masih mencatat laba bersih yang melonjak tiga kali lipat jadi Rp15,34 miliar, tapi arus kas operasinya berbalik negatif dan kas perusahaan menyusut separuh. Arahnya sudah terlihat jelas memburuk di sektor ini, yang akan menegaskannya adalah apakah WIKA berhasil menjadwalkan ulang RUPSU berikutnya atau PTPP bisa melunasi kupon susulan sebelum jatuh ke status gagal bayar penuh."
   },
   {
    "judul": "Buyback Darurat Meluas ke Emiten Besar",
    "isi": "Pola buyback yang muncul kemarin kini terlihat lebih sistemik, bukan sekadar kasus satu dua emiten. Indofood, Indofood CBP, dan London Sumatra sama-sama menyiapkan buyback maksimal Rp750 miliar dari kas internal dengan periode yang sama, 26 Oktober hingga 31 Desember 2026, memakai aturan OJK soal pasar bergejolak. Padahal pada hari pengumuman ini IHSG justru menguat 0,95 persen ke 5.439,26, bukan sedang jatuh tajam seperti kondisi yang biasanya memicu aturan itu. Arah polanya sudah jelas meluas, dari sekadar respons darurat menjadi semacam cara baku memakai kas perusahaan besar. Hal yang akan menegaskan apakah ini terus berlanjut adalah sikap OJK menjelang akhir tahun, apakah kelonggaran aturan buyback tanpa RUPS ini diperpanjang atau dicabut begitu volatilitas pasar mengendur."
   },
   {
    "judul": "Dilusi Saham Non-Proporsional Terus Muncul",
    "isi": "Di tengah OJK mencatat total denda Rp2,52 triliun ke pelanggar pasar modal, dengan tiga kasus DSSA, BREN, dan CUAN menyumbang Rp2,1 triliun atau sekitar 83 persen dari seluruhnya, kasus dilusi baru tetap bermunculan dari emiten lain. VIVA mengonfirmasi dilusi 72,35 persen dari penambahan modal tanpa hak memesan efek terlebih dahulu ke dua pihak afiliasi pengendali, menekan free float publik ke 15,04 persen. UVCR merevisi rencana serupa, menerbitkan hingga 200 juta saham baru atau 9,99 persen ke satu investor tunggal tanpa ditawarkan ke pemegang saham lama. UNSP memang berhasil membalik ekuitas jadi positif Rp2,77 triliun, tetapi lewat konversi utang yang mendilusi pemegang saham lama hingga 13 kali lipat. Arahnya sudah jelas, pola penambahan modal yang menggerus porsi pemegang saham publik ini terus berjalan meski pengawasan pasar modal sedang disorot."
   }
  ],
  "penutup": "Yang paling menentukan pekan depan adalah mulainya periode buyback massal pada 26 Oktober dan apakah PTPP serta WIKA bisa keluar dari status gagal bayar sebelum tenggat pembayaran berikutnya.",
